<?php
/** Buyer order portal served through a high-entropy emailed capability link. */
namespace PassCaptain;

if ( ! defined( 'ABSPATH' ) ) { exit; }

final class OrderPortal {
	public static function register() {
		add_filter( 'query_vars', static function ( $vars ) { $vars[] = 'wpcap_order'; $vars[] = 'wpcap_access'; return $vars; } );
		add_action( 'template_redirect', array( __CLASS__, 'maybe_render' ) );
	}

	public static function maybe_render() {
		$public_id = sanitize_text_field( get_query_var( 'wpcap_order' ) );
		$token = strtolower( preg_replace( '/[^a-f0-9]/', '', (string) get_query_var( 'wpcap_access' ) ) );
		if ( '' === $public_id || '' === $token ) { return; }
		global $wpdb;
		$order = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$wpdb->prefix}wpcap_orders WHERE public_id=%s", $public_id ) );
		if ( ! $order || ! $order->access_expires_at || $order->access_expires_at <= current_time( 'mysql', true ) || 64 !== strlen( $token ) || ! hash_equals( (string) $order->access_token_hash, hash( 'sha256', $token ) ) ) { status_header( 404 ); exit; }
		header( 'Content-Type: text/html; charset=' . get_bloginfo( 'charset' ) );
		header( 'Cache-Control: no-store, no-cache, must-revalidate, max-age=0' );
		header( 'Referrer-Policy: no-referrer' );
		$tickets = $wpdb->get_results( $wpdb->prepare(
			"SELECT t.public_id,t.status,t.transfer_count,t.attendee_email,ta.attendee_name,tt.name AS ticket_name,e.name AS event_name,o.starts_at,o.timezone FROM {$wpdb->prefix}wpcap_tickets t LEFT JOIN {$wpdb->prefix}wpcap_ticket_assignments ta ON ta.ticket_id=t.ticket_id INNER JOIN {$wpdb->prefix}wpcap_ticket_types tt ON tt.ticket_type_id=t.ticket_type_id INNER JOIN {$wpdb->prefix}wpcap_occurrences o ON o.occurrence_id=tt.occurrence_id INNER JOIN {$wpdb->prefix}wpcap_events e ON e.event_id=o.event_id WHERE t.order_id=%d ORDER BY t.ticket_id",
			$order->order_id
		) );
		$transfer_url = rest_url( 'wp-pass-captain/v1/orders/' . rawurlencode( $public_id ) . '/transfer' );
		?><!doctype html><html lang="<?php echo esc_attr( determine_locale() ); ?>"><head><meta charset="<?php bloginfo( 'charset' ); ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php esc_html_e( 'Deine Bestellung', 'wp-pass-captain' ); ?></title><style>body{font:16px/1.5 system-ui,sans-serif;max-width:48rem;margin:2rem auto;padding:0 1rem;color:#1d2327}.card{border:1px solid #c3c4c7;border-radius:10px;padding:1rem;margin:1rem 0}label{display:grid;gap:.25rem;margin:.5rem 0}input{max-width:28rem;padding:.5rem}button{padding:.55rem 1rem}.status{font-weight:700}</style></head><body><main><h1><?php esc_html_e( 'Deine Bestellung', 'wp-pass-captain' ); ?></h1><p><?php echo esc_html( $order->public_id ); ?></p><p class="status"><?php echo esc_html( $order->status . ' / ' . $order->payment_status ); ?></p><p><?php echo esc_html( number_format_i18n( $order->total_minor / 100, 2 ) . ' ' . $order->currency ); ?></p><?php if ( $tickets ) : ?><h2><?php esc_html_e( 'Tickets', 'wp-pass-captain' ); ?></h2><?php foreach ( $tickets as $ticket ) : ?><section class="card"><h3><?php echo esc_html( $ticket->event_name . ' — ' . $ticket->ticket_name ); ?></h3><p><?php echo esc_html( wp_date( 'd.m.Y H:i', strtotime( $ticket->starts_at . ' UTC' ), new \DateTimeZone( $ticket->timezone ) ) . ' ' . $ticket->timezone ); ?></p><p><?php echo esc_html( __( 'Status:', 'wp-pass-captain' ) . ' ' . $ticket->status ); ?></p><?php if ( 'valid' === $ticket->status && strtotime( $ticket->starts_at . ' UTC' ) > time() ) : ?><form class="wpcap-assignment-form"><input type="hidden" name="ticket_public_id" value="<?php echo esc_attr( $ticket->public_id ); ?>"><label><?php esc_html_e( 'Teilnehmername', 'wp-pass-captain' ); ?><input name="attendee_name" type="text" maxlength="190" value="<?php echo esc_attr( $ticket->attendee_name ?? '' ); ?>" required></label><label><?php esc_html_e( 'Teilnehmer-E-Mail', 'wp-pass-captain' ); ?><input name="attendee_email" type="email" autocomplete="email" value="<?php echo esc_attr( $ticket->attendee_email ); ?>" required></label><button type="submit"><?php esc_html_e( 'Teilnehmer zuweisen', 'wp-pass-captain' ); ?></button><p class="message" aria-live="polite"></p></form><?php endif; ?><?php if ( 'valid' === $ticket->status && 0 === (int) $ticket->transfer_count && strtotime( $ticket->starts_at . ' UTC' ) > time() ) : ?><form class="wpcap-transfer-form"><input type="hidden" name="ticket_public_id" value="<?php echo esc_attr( $ticket->public_id ); ?>"><label><?php esc_html_e( 'An E-Mail übertragen', 'wp-pass-captain' ); ?><input name="recipient_email" type="email" autocomplete="email" required></label><button type="submit"><?php esc_html_e( 'Ticket einmalig übertragen', 'wp-pass-captain' ); ?></button><p class="message" aria-live="polite"></p></form><?php endif; ?></section><?php endforeach; endif; ?><p><?php esc_html_e( 'Diesen persönlichen Link sicher aufbewahren und nicht teilen.', 'wp-pass-captain' ); ?></p></main><script>document.querySelectorAll('.wpcap-transfer-form').forEach(function(form){form.addEventListener('submit',async function(event){event.preventDefault();const message=form.querySelector('.message');const button=form.querySelector('button');button.disabled=true;try{const response=await fetch(<?php echo wp_json_encode( $transfer_url ); ?>,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({access_token:<?php echo wp_json_encode( $token ); ?>,ticket_public_id:form.ticket_public_id.value,recipient_email:form.recipient_email.value})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Übertragung fehlgeschlagen.');message.textContent='Ticket wurde übertragen. Der neue Code wurde per E-Mail versendet.';form.remove();}catch(error){message.textContent=error.message;button.disabled=false;}});});document.querySelectorAll('.wpcap-assignment-form').forEach(function(form){form.addEventListener('submit',async function(event){event.preventDefault();const message=form.querySelector('.message');try{const response=await fetch(<?php echo wp_json_encode( rest_url( 'wp-pass-captain/v1/orders/' . rawurlencode( $public_id ) . '/assign' ) ); ?>,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({access_token:<?php echo wp_json_encode( $token ); ?>,ticket_public_id:form.ticket_public_id.value,attendee_name:form.attendee_name.value,attendee_email:form.attendee_email.value})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Zuweisung fehlgeschlagen.');message.textContent='Teilnehmer wurde zugewiesen. Ein aktualisierter Ticketcode wurde versendet.';}catch(error){message.textContent=error.message;}});});</script></body></html><?php
		exit;
	}
}
